#include <algorithm>
#include <array>
#include <deque>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <stdexcept>
#include <vector>
using namespace std;using ll=long long;using G=vector<int>;using S=array<ll,4>;using Recipe=vector<pair<int,int>>;
void need(bool b,const char*s){if(!b)throw runtime_error(s);}bool arc(const G&a,int i,int j){return a[i]>>j&1;}
G graph(int n,int code){G a(n);int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++)if(code>>k&1)a[i]|=1<<j;else a[j]|=1<<i;return a;}
G induced(const G&a,const vector<int>&v){G b(v.size());for(int i=0;i<(int)v.size();i++)for(int j=0;j<(int)v.size();j++)if(arc(a,v[i],v[j]))b[i]|=1<<j;return b;}
G opposite(G a){int n=a.size();for(int i=0;i<n;i++)a[i]^=((1<<n)-1)^(1<<i);return a;}
ll literalH(const G&a){int n=a.size();if(!n)return 1;vector<int>p(n);iota(p.begin(),p.end(),0);ll h=0;do{bool ok=true;for(int i=1;i<n;i++)if(!arc(a,p[i-1],p[i])){ok=false;break;}h+=ok;}while(next_permutation(p.begin(),p.end()));return h;}
ll literalC(const G&a){int n=a.size();if(n<3)return 0;vector<int>p(n-1);iota(p.begin(),p.end(),1);ll c=0;do{bool ok=arc(a,0,p[0])&&arc(a,p.back(),0);for(int i=1;i<n-1&&ok;i++)ok=arc(a,p[i-1],p[i]);c+=ok;}while(next_permutation(p.begin(),p.end()));return c;}
struct Profile{ll H;vector<ll>s,e,R;vector<vector<ll>>K;};
Profile profile(const G&a){int n=a.size();Profile z{0,vector<ll>(n),vector<ll>(n),vector<ll>(n),vector<vector<ll>>(n,vector<ll>(n))};vector<int>p(n);iota(p.begin(),p.end(),0);do{bool hp=true;for(int i=1;i<n;i++)hp&=arc(a,p[i-1],p[i]);if(hp){z.H++;z.s[p.front()]++;z.e[p.back()]++;}for(int cut=0;cut<n;cut++){bool ok=true;for(int j=1;j<n;j++)if(j!=cut&&!arc(a,p[j-1],p[j])){ok=false;break;}if(ok){z.R[p[cut]]++;if(cut)z.K[p[cut-1]][p[cut]]++;}}}while(next_permutation(p.begin(),p.end()));return z;}
S source_profile(const G&a,int root){auto p=profile(a);need(p.s[root]==1,"physical source starts1");vector<int>v;for(int i=0;i<(int)a.size();i++)if(i!=root)v.push_back(i);return {p.H,p.e[root],p.R[root],literalH(induced(a,v))};}
array<ll,3>constants(int L){if(L==1)return{1,1,1};int n=L-1,k=32-__builtin_clz((unsigned)n);ll f=1,x=0,Q=1;for(int j=k-1;j>=0;j--){if(n>>j&1)x=2*x+1;else{f+=x+x%2;x*=2;}}for(int i=0;i<k;i++)if(!(n>>i&1))Q+=1LL<<(k-1-i);return{f,Q,1LL<<k};}
G gadget(int L){int x=L-1,k=x?32-__builtin_clz((unsigned)x):0;G a(k+1);for(int i=0;i<k;i++){for(int j=i+1;j<k;j++)a[i]|=1<<j;if(x>>i&1)a[i]|=1<<k;else a[k]|=1<<i;}return a;}
pair<G,int>graft(const G&a,const vector<int>&entries,const G&b,int root){int n=a.size(),m=b.size();G c(n+m);for(int i=0;i<n;i++)c[i]=a[i];for(int j=0;j<m;j++)c[n+j]=b[j]<<n;for(int i=0;i<n;i++)for(int j=0;j<m;j++)if(j==root&&find(entries.begin(),entries.end(),i)!=entries.end())c[n+j]|=1<<i;else c[i]|=1<<(n+j);return{c,n+root};}
pair<G,int>build(const Recipe&r){G a={0};int root=0;for(auto[k,L]:r)if(k==0){int n=a.size();for(int&i:a)i|=1<<n;a.push_back(0);}else{auto b=gadget(L);auto z=graft(a,{root},b,b.size()-1);a=z.first;root=z.second;}return{a,root};}
array<ll,4>left(int kind,S v){auto[D,E,U,d]=v;if(kind==0)return{D-E+U,D-E+d,D+3*U-d,U+E};return{D+2*U,U+d,2*D-E+6*U-d,U+E};}
ll val(int kind,S v,S w){auto[h,E,R,K]=left(kind,v);return h*w[0]-E*w[1]+R*w[2]-K*w[3];}
pair<G,int>make(int kind,const G&V,int c,const G&W,int a){auto z=graft(V,{c},G{0},0);vector<int>entries={z.second,c};if(kind){z=graft(z.first,{z.second},G{0},0);entries={z.second,c};}return graft(z.first,entries,opposite(W),a);}
pair<ll,ll>backward(const G&a){int n=a.size(),N=1<<n;vector<ll>H((ll)N*n),C((ll)N*n);for(int v=0;v<n;v++){H[(1<<v)*n+v]=1;if(v)C[(1<<v)*n+v]=arc(a,v,0);}for(int S=1;S<N;S++)if((S&(S-1))!=0)for(int v=0;v<n;v++)if(S>>v&1){int rest=S^(1<<v),out=a[v]&rest;while(out){int w=__builtin_ctz((unsigned)out);out&=out-1;H[S*n+v]+=H[rest*n+w];if(!(S&1))C[S*n+v]+=C[rest*n+w];}}ll h=0,c=0;for(int v=0;v<n;v++){h+=H[(N-1)*n+v];if(arc(a,0,v))c+=C[(N-2)*n+v];}return{h,c};}
int factors(const G&T){int n=T.size(),count=0;for(int mask=1;mask<(1<<n);mask++){int size=__builtin_popcount((unsigned)mask);if(size<3||size>n-2)continue;vector<int>L,Widx;for(int i=0;i<n;i++)(mask>>i&1?L:Widx).push_back(i);for(int r:Widx){int E=T[r]&mask;if(__builtin_popcount((unsigned)E)!=2)continue;bool cross=true;for(int s:Widx)if(s!=r&&(T[s]&mask))cross=false;if(!cross)continue;vector<int>entries;for(int v:L)if(E>>v&1)entries.push_back(v);G W=opposite(induced(T,Widx));int wr=find(Widx.begin(),Widx.end(),r)-Widx.begin();if(profile(W).s[wr]!=1)continue;
for(int kind=0;kind<2;kind++)for(int swap=0;swap<2;swap++){int u=entries[swap],c=entries[1-swap],b=-1;if(!kind){if((T[u]&mask)!=(1<<c))continue;}else{int out=T[u]&mask;if(__builtin_popcount((unsigned)out)!=1)continue;b=__builtin_ctz((unsigned)out);if(b==c||E>>b&1||(T[b]&mask)!=(1<<c))continue;}vector<int>keep;for(int v:L)if(v!=u&&v!=b)keep.push_back(v);if(keep.size()<2)continue;G V=induced(T,keep);int cr=find(keep.begin(),keep.end(),c)-keep.begin();if(profile(V).s[cr]!=1)continue;auto vv=source_profile(V,cr),ww=source_profile(W,wr);auto A=make(kind,V,cr,W,wr).first;vector<int>order=keep;if(kind)order.push_back(b);order.push_back(u);order.insert(order.end(),Widx.begin(),Widx.end());need(A.size()==T.size(),"factor order");for(int i=0;i<n;i++)for(int j=0;j<n;j++)need(arc(A,i,j)==arc(T,order[i],order[j]),"independent exhaustive exact graft reconstruction");need(val(kind,vv,ww)==literalH(T),"factor scalar literal H");count++;}}}return count;}
int main(){ll labelled=0,nonregular=0,leftcontrols=0,arbitrary=0;for(int n=3;n<=6;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){G T=graph(n,code);if(literalC(T)!=2)continue;int f=factors(T);bool R5=n==5&&all_of(T.begin(),T.end(),[](int r){return __builtin_popcount((unsigned)r)==2;});need(f==(R5?0:1),"unique exhaustive source presentation");labelled++;nonregular+=!R5;}
vector<tuple<G,int,Profile>>rights;for(int n=1;n<=4;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){G a=graph(n,code);auto p=profile(a);for(int r=0;r<n;r++)rights.push_back({a,r,p});}
for(int n=2;n<=3;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){G a=graph(n,code);auto p=profile(a);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){ll E=p.e[i]+p.e[j],R=p.R[i]+p.R[j],K=p.K[i][j]+p.K[j][i];need(E<=p.H&&K<=R&&R-K>=p.H,"literal pair inequalities");for(auto &[b,r,q]:rights){vector<int>rest;for(int x=0;x<(int)b.size();x++)if(x!=r)rest.push_back(x);ll d=literalH(induced(b,rest));auto qb=profile(opposite(b));ll L=qb.R[r];auto out=graft(a,{i,j},b,r).first;need(literalH(out)==p.H*q.H-E*q.s[r]+R*L-K*d,"arbitrary right graft literal");if(b.size()>1)need(literalC(out)==(p.s[i]+p.s[j])*q.e[r],"arbitrary right cycle literal");arbitrary++;}}}
for(int n=1;n<=5;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){G a=graph(n,code);auto p=profile(a);for(int r=0;r<n;r++)if(p.s[r]==1){S v=source_profile(a,r);auto one=graft(a,{r},G{0},0);for(int kind=0;kind<2;kind++){if(!kind&&n==1)continue;auto out=one;int x=out.second;if(kind){out=graft(out.first,{x},G{0},0);x=out.second;}auto q=profile(out.first);array<ll,4>got={q.H,q.e[x]+q.e[r],q.R[x]+q.R[r],q.K[x][r]+q.K[r][x]};need(got==left(kind,v),"literal source left response");need(literalC(out.first)==1&&q.s[x]==1&&q.s[r]==1,"left pair C1 starts");leftcontrols++;}}}
int cap=310;map<S,Recipe>B;deque<S>Q;S base={1,1,1,1};B[base]={};Q.push_back(base);while(!Q.empty()){S v=Q.front();Q.pop_front();auto[D,E,U,d]=v;vector<pair<S,pair<int,int>>> moves={{{D,0,2*U,d},{0,0}}};for(int L=1;L<=cap/U;L++){auto[g,q,b]=constants(L);moves.push_back({{g*D-(L%2)*E+L*U,D-(L==1)*E,q*D+b*U,D},{1,L}});}for(auto&[w,move]:moves)if(w[2]<=cap&&!B.count(w)){Recipe r=B[v];r.push_back(move);B[w]=r;Q.push_back(w);}}
int oracle=0;for(auto&[s,r]:B)if(s[2]<=40){auto a=build(r);need(source_profile(a.first,a.second)==s,"literal full oracle profile");oracle++;}
vector<S>states;for(auto&[s,r]:B)if(s!=base)states.push_back(s);map<int,tuple<int,S,S>>support;support[15]={2,base,base};ll fullpairs=0;for(int kind=0;kind<2;kind++)for(int i=0;i<(int)states.size();i++)for(int j=i;j<(int)states.size();j++){auto v=states[i],w=states[j];ll H=val(kind,v,w);need(H==val(kind,w,v),"scalar symmetry");ll lo=kind?6*v[2]*w[2]+v[2]+w[2]+1:3*v[2]*w[2]+1;need(H>=lo,"positive product bound");if(H<=1861)support.emplace(H,make_tuple(kind,v,w));fullpairs++;}
need(B.size()==2048&&support.size()==884,"independent full pair census");int maxorder=0,physical=0;for(auto&[H,rec]:support){auto[k,v,w]=rec;if(k==2)continue;auto V=build(B[v]),W=build(B[w]);auto T=make(k,V.first,V.second,W.first,W.second).first;maxorder=max(maxorder,(int)T.size());need(T.size()<=18,"witness order capacity");need(backward(T)==make_pair((ll)H,2LL),"all bounded physical witness counts");physical++;}
cout<<"{\n  \"status\":\"PASS\",\n  \"labelled_C2_graphs\":"<<labelled<<",\n  \"unique_nonregular_presentations\":"<<nonregular<<",\n  \"literal_arbitrary_grafts\":"<<arbitrary<<",\n  \"literal_left_responses\":"<<leftcontrols<<",\n  \"source_states\":"<<B.size()<<",\n  \"literal_oracle_profiles\":"<<oracle<<",\n  \"unpruned_bilinear_pairs\":"<<fullpairs<<",\n  \"physical_support_graphs\":"<<physical<<",\n  \"maximum_witness_order\":"<<maxorder<<",\n  \"support\":[";bool first=true;for(auto&[H,r]:support){if(!first)cout<<",";first=false;cout<<H;}cout<<"]\n}\n";
}
